def support(scratch, tree, spec_targets, added=(), modules=(), fresh=()):
    folder = Path(scratch)/'side-by-side'
    (folder/'out').mkdir(parents=True, exist_ok=True)
    (folder/'hook').mkdir(exist_ok=True)
    (folder/'hook'/'sitecustomize.py').write_text(HOOK)
    rows = [dict(t, file=str(Path(tree)/t['file'])) for t in spec_targets]
    extra = [dict(a, file=str(Path(tree)/a['file'])) for a in added]
    new = [dict(m, file=str(Path(tree)/m['file'])) for m in modules]
    classes = {}
    for cls, attr in sorted(fresh):
        classes.setdefault(cls, []).append(attr)
    (folder/'spec.json').write_text(json.dumps(dict(root=str(tree), targets=rows, additions=extra, modules=new, calls=CALLS,
                                                    shapes=SHAPES, fresh=classes)))
    return folder


def fresh_attributes(before, after):
    """(class, attribute) pairs the change starts setting when an object is built, in one file: ``self.name = ...``
    inside ``__init__``, ``__new__`` or ``__post_init__`` of a class (or of a base class defined in the same file) in
    ``after`` and not in that class in ``before``. Every object of that class the code after the change builds has them;
    one the code before it built does not. Per class, not per file: another class of the file already setting the name
    before the change says nothing about this one (Flask #5812: the old ``RequestContext`` set
    ``_after_request_functions``; the new ``AppContext`` does). (An attribute set by some other method is left out: an
    object built after the change can lack it too, so missing it may be a real regression.)"""
    def names(text):
        try:
            tree = ast.parse(text or '')
        except (SyntaxError, ValueError):
            return {}
        own, bases = {}, {}
        for node in ast.walk(tree):
            if not isinstance(node, ast.ClassDef):
                continue
            bases[node.name] = [b.id for b in node.bases if isinstance(b, ast.Name)]
            found = own.setdefault(node.name, set())
            for item in node.body:
                if isinstance(item, (ast.FunctionDef, ast.AsyncFunctionDef)) and item.name in ('__init__', '__new__', '__post_init__'):
                    for inner in ast.walk(item):
                        if isinstance(inner, ast.Attribute) and isinstance(inner.ctx, ast.Store) and isinstance(inner.value, ast.Name) \
                                and inner.value.id in ('self', 'cls', 'obj', 'instance'):
                            found.add(inner.attr)

        def every(name, seen=()):
            if name in seen or name not in own:
                return set()
            return own[name].union(*(every(b, (*seen, name)) for b in bases.get(name, ())))
        return {name: every(name) for name in own}
    old, new = names(before), names(after)
    return {(cls, attr) for cls, attrs in new.items() for attr in attrs - old.get(cls, set())}


ATTRIBUTE = re.compile(r"'(\w+)' object has no attribute '(\w+)'")


def run(runner, python, before_tree, ids, spec_targets, skipped, scratch, timeout, added=(), modules=(), prefer=(),
        fresh=()):
    """Run ``ids`` on the code before the change with the hook. Returns (info, differences, gaps). Tests in ``prefer``
    (seen running a changed line) run first, so theirs are the calls a full shape keeps."""
    gaps = []
    first = set(prefer)
    ids = sorted(ids, key=lambda i: not any(i == p or i.startswith(p + '::') for p in first)) if first else list(ids)
    if not spec_targets:
        return dict(targets=0, skipped=skipped), [], gaps
    folder = support(scratch, before_tree, spec_targets, added, modules, fresh)
    env = dict(AMU_TRUST_PATH=str(folder/'hook'), AMU_SBS_SPEC=str(folder/'spec.json'), AMU_SBS_OUT=str(folder/'out'))
    outcomes, problem = runners.execute(runner, python, before_tree, ids, Path(scratch)/'side-by-side.xml', timeout, extra_env=env)
    if problem and problem != 'timed out':
        gaps.append(f'side-by-side run ({runner.name}): {problem}')
    elif problem:
        gaps.append('side-by-side run stopped at its time limit; calls captured until then are compared')
    stopped = problem == 'timed out'
    results, captured, misfit_calls = [], {}, 0
    for part in sorted((folder/'out').glob('*.jsonl')):
        try:
            lines = part.read_text().splitlines()
        except OSError:
            continue
        for line in lines:
            try:
                event = json.loads(line)
            except ValueError:
                continue  # a line cut short by the time limit
            kind = event.pop('kind', None)
            if kind == 'result':
                results.append(event)
            elif kind == 'skipped':
                skipped[event['target']] = event['reason']
            elif kind == 'captured':
                captured[event['target']] = captured.get(event['target'], 0) + 1
            elif kind == 'misfit':
                misfit_calls += 1
    # An object built by the code before the change lacks state a changed method now gives it. When one changed method
    # of a class changes the object's state, an AttributeError from another changed method of that class says the input
    # was built by the old code, not that the method behaves differently: set aside, and counted.
    stateful = {row['target'].rsplit('.', 1)[0] for row in results
                if row['stable'] and 'args_after' in row['differs'] and '.' in row['target'].split('#', 1)[1]}
    # A call captured from the old code does not fit a function whose parameters the change altered: the as-changed
    # version refuses it at the call. That is a different signature, not a behaviour seen on the input: set aside.
    reshaped = {t['id'] for t in spec_targets if t.get('signature_changed')}
    seen, differences, built_before, misfit = set(), [], 0, misfit_calls
    for row in results:
        after = row['after']['result']
        if (row['target'] in reshaped and after[0] == 'raise' and after[1] == 'TypeError'
                and after[2].startswith(row['target'].rsplit('#', 1)[1] + '()') and 'argument' in after[2]):
            misfit += 1
            continue
        if row['stable'] and row['differs'] and after[0] == 'raise' and row['after'].get('old_object') \
                and row['before']['result'][:2] != after[:2]:
            # The as-changed code failed inside a method of an object the code before the change built (it lacks an
            # attribute the new constructor always sets): the input's state, not the behaviour.
            built_before += 1
            continue
        missing = ATTRIBUTE.search(after[2]) if after[0] == 'raise' and after[1] == 'AttributeError' else None
        if row['stable'] and row['differs'] and missing and (missing[1], missing[2]) in fresh and row['before']['result'][:2] != after[:2]:
            # The changed code reads an attribute the change starts setting, on an object the code before it built
            # (Flask #5812: 'AppContext' object has no attribute '_request'): the input, not the behaviour.
            built_before += 1
            continue
        if (row['stable'] and row['differs'] and row['target'].rsplit('.', 1)[0] in stateful and 'args_after' not in row['differs']
                and after[0] == 'raise' and after[1] == 'AttributeError' and row['before']['result'][0] != 'raise'):
            built_before += 1
            continue
        if row['stable'] and row['differs']:
            key = (row['target'], row['input'])
            if key not in seen:
                seen.add(key)
                differences.append(dict(row, label=KIND))
    info = dict(targets=len(spec_targets), compared_calls=len(results), functions_called=len(captured), called=sorted(captured),
                unstable=sum(not r['stable'] for r in results), differences=len(differences), skipped=skipped,
                input_built_before_the_change=built_before, calls_not_fitting_a_changed_signature=misfit)
    # Which calls were compared: per target, its argument shape, the input and the test it came from.
    info['captured'] = [dict(target=r['target'], shape=r.get('shape', '?'), input=str(r.get('input', ''))[:200],
                             test=str(r.get('test', ''))[:200]) for r in results[:LISTED]]
    if len(results) > LISTED:
        info['captured_not_listed'] = len(results) - LISTED
    if stopped:
        info['stopped'] = True  # calls after the time limit were not seen: none captured does not mean none made
    # Only a run that read some test outcome can say no changed function was called: a runner that never started,
    # or ran nothing, saw no calls at all (its own gap says why).
    if not results and any(state != 'unrunnable' for state in outcomes.values()):
        gaps.append(f'side-by-side: none of the {len(spec_targets)} comparable changed function(s) was called by the tests run on the code before the change')
    return info, differences, gaps

def dotted(ident, strip=''):
    path, *rest = ident.split('::')
    path = path[len(strip):] if strip and path.startswith(strip) else path
    return '.'.join([path[:-3].replace('/', '.'), *rest])


class Runner:
    name = 'pytest'
    needs_class = False
    parallel = False  # whether several processes may run tests in the same tree at once

    def __init__(self):
        self.refused = {}  # {(tree, group): what the runner said} for label groups it refused in that tree (refusal)

    def label(self, ident):
        return ident

    def group(self, ident):
        """The group a label belongs to that a runner can refuse as a whole, such as a Django test app. None for
        pytest: its labels are files, and a file it cannot collect is not a group."""
        return None

    def cwd(self, tree):
        return tree

    extra = ()  # arguments added to every run, such as the ordering seed (trust.ordering)
    durations = None  # {id: seconds} measured by the runs of this instance, where the runner reports them

    def command(self, python, labels, report):
        return [python, '-m', 'pytest', *labels, '-q', '-p', 'no:cacheprovider', *self.extra, '--junitxml=' + str(report)]

    def paste(self, ident):
        return 'python -m pytest ' + self.label(ident)

    def selected(self, python, tree, ids, env, timeout):
        """The ids pytest still selects under the project's own configuration (a marker filter in addopts deselects
        tests even when they are named); None when that cannot be read."""
        try:
            done = subprocess.run([python, '-m', 'pytest', '--collect-only', '-q', '-p', 'no:cacheprovider', *self.extra,
                                   *[self.label(i) for i in ids]],
                                  cwd=self.cwd(tree), env=env, capture_output=True, timeout=timeout, stdin=subprocess.DEVNULL)
        except (subprocess.TimeoutExpired, OSError):
            return None
        return {re.sub(r'\[.*\]$', '', line.strip()) for line in done.stdout.decode(errors='replace').splitlines() if '::' in line}

    def outcomes(self, tree, output, report, ids):
        found = {}
        try:
            cases = list(ET.parse(report).getroot().iter('testcase'))
        except (OSError, ET.ParseError):
            return found
        for case in cases:
            parts = case.get('classname', '').split('.')
            for cut in range(len(parts), 0, -1):
                if (tree/('/'.join(parts[:cut]) + '.py')).is_file():
                    break
            else:
                continue
            ident = '::'.join(['/'.join(parts[:cut]) + '.py', *parts[cut:], case.get('name', '').split('[')[0]])
            try:
                took = float(case.get('time') or 0)
            except ValueError:
                took = 0.0
            if self.durations is None:
                self.durations = {}
            self.durations[ident] = round(self.durations.get(ident, 0.0) + took, 3) if ident in found else round(took, 3)
            state = next((child.tag for child in case if child.tag in ('failure', 'error', 'skipped')), 'passed')
            state = 'failed' if state in ('failure', 'error') else state
            # A function fails if any of its parameter instances fails.
            if ORDER[state] > ORDER.get(found.get(ident), 0):
                found[ident] = state
        return found


    def failure_texts(self, tree, output, report, ids):
        """{id: what the report says about the test's failure or error}, from the JUnit report."""
        texts = {}
        try:
            cases = list(ET.parse(report).getroot().iter('testcase'))
        except (OSError, ET.ParseError):
            return texts
        for case in cases:
            said = ''.join((child.get('message') or '') + '\n' + (child.text or '') + '\n'
                           for child in case if child.tag in ('failure', 'error'))
            if not said:
                continue
            if not case.get('classname'):
                # A module that cannot be collected: its error goes to every requested test in that file.
                path = case.get('name', '').replace('.', '/') + '.py'
                for ident in ids:
                    if ident.split('::')[0] == path:
                        texts[ident] = texts.get(ident, '') + said
                continue
            parts = case.get('classname', '').split('.')
            for cut in range(len(parts), 0, -1):
                if (tree/('/'.join(parts[:cut]) + '.py')).is_file():
                    break
            else:
                continue
            ident = '::'.join(['/'.join(parts[:cut]) + '.py', *parts[cut:], case.get('name', '').split('[')[0]])
            texts[ident] = texts.get(ident, '') + said
        return texts


class Unittest(Runner):
    """``python -m unittest`` and the Django runners share verbose output and dotted labels."""
    if any(module.split('.')[0] == 'pytest_randomly' for _, module in found):
        kept.append('pytest_randomly')
    return [arg for module in kept for arg in ('-p', module)]


def environment(tree, extra_env=None, autoload=True):
    """The environment a test run gets: the tree importable, no bytecode written, a fixed hash seed so both sides
    iterate sets and dicts of strings alike. ``AMU_TRUST_PATH`` in ``extra_env`` goes first on the path (trust)."""
    extra = dict(extra_env or {})
    first = extra.get('AMU_TRUST_PATH')
    if not autoload:
        extra.setdefault('PYTEST_DISABLE_PLUGIN_AUTOLOAD', '1')
    # The project's tests never see AMU's model credentials: the change under test is someone else's code.
    inherited = {k: v for k, v in os.environ.items() if not k.startswith(SECRETS)}
    return dict(inherited, PYTHONDONTWRITEBYTECODE='1', PYTHONHASHSEED='0', **extra,
                PYTHONPATH=os.pathsep.join(filter(None, [first, str(tree/'src'), str(tree), os.environ.get('PYTHONPATH')])))


def sequence(runner, python, tree, ids, timeout):
    """Each label's outcomes in the order a unittest-style runner reported them: {id: [state, ...]}. A label given
    twice runs twice in the same process."""
    try:
        done = subprocess.run(runner.command(python, [runner.label(i) for i in ids], None), cwd=runner.cwd(tree),
                              env=environment(tree, autoload=not getattr(runner, 'autoload_off', False)), capture_output=True,
                              timeout=timeout, stdin=subprocess.DEVNULL)
    except (subprocess.TimeoutExpired, OSError):
        return {}
    by_label = {runner.label(ident): ident for ident in ids}
    found, pending = {}, None
    for line in (done.stderr + done.stdout).decode(errors='replace').splitlines():
        match = VERBOSE.match(line)
        if match:
            pending = match[2]
        state = STATE.search(line)
        if state and pending:
            value = 'passed' if state[1] == 'ok' else 'skipped' if state[1] in ('skipped', 'expected failure') else 'failed'
            if pending in by_label:
                found.setdefault(by_label[pending], []).append(value)
            pending = None
    return found


def execute(runner, python, tree, ids, report, timeout, extra_env=None, extra_args=None, texts=None):
    """Run ``ids`` in ``tree``. Returns ({id: state}, problem or None).

    ``texts``, a dict when given, gets what the runner printed about each test that did not pass:
    {id: {'text': ..., 'own': True}} from the test's own failure report, or {'text': <the run's output>, 'own': False}
    when the runner said nothing about the test itself (a module that does not load)."""
    usable = [ident for ident in ids if not runner.needs_class or ident.count('::') >= 2]
    if not usable:
        return {}, None
    env = environment(tree, extra_env, autoload=not getattr(runner, 'autoload_off', False))
    # A label group the runner refused in this tree is not offered again: its labels are unrunnable up front.
    where = str(tree)
    found, problem, first_error = {i: 'unrunnable' for i in usable if (where, runner.group(i)) in runner.refused}, None, None
    # One batch first. A single label the runner cannot load can abort the whole batch and leave it with
    # no outcomes, so a batch that comes back short is split in two and retried until the labels that
    # cannot be run stand alone. Those are returned as 'unrunnable': never silently as "did not fail".
    # ``timeout`` bounds the whole call, splits included: each retry gets what is left, not the full limit again.
    batches, splits, deadline = [[i for i in usable if i not in found]], 0, time.monotonic() + timeout
    while batches:
        batch = batches.pop(0)
        if not batch:
            continue
        left = deadline - time.monotonic()
        if left <= 0:
            return found, 'timed out'
        try:
            command = runner.command(python, [runner.label(i) for i in batch], report)
            if extra_args:
                command = [*command[:3], *extra_args, *command[3:]] if runner.name == 'pytest' else command
            done = subprocess.run(command, cwd=runner.cwd(tree), env=env,
                                  capture_output=True, timeout=left, stdin=subprocess.DEVNULL)
        except subprocess.TimeoutExpired:
            return found, 'timed out'
        except OSError as exc:
            if exc.errno == errno.E2BIG and len(batch) > 1:
                # Too many labels for one command line (Django #22026: 17,539). Not the labels' fault: run them in
                # halves, in order, without spending the splits kept for isolating labels that abort a batch.
                half = len(batch) // 2
                batches[:0] = [batch[:half], batch[half:]]
                continue
            return found, f'could not start the test runner: {exc.strerror}'
        output = (done.stderr + done.stdout).decode(errors='replace')
        got = runner.outcomes(tree, output, report, batch)
        found.update(got)
        if texts is not None:
            own = runner.failure_texts(tree, output, report, batch)
            for ident in batch:
                if got.get(ident) == 'passed' or got.get(ident) == 'skipped':
                    continue
                if ident in own:
                    texts[ident] = dict(text=own[ident][-TEXT:], own=True)
                elif ident not in texts or not texts[ident]['own']:
                    texts[ident] = dict(text=output[-TEXT:], own=False)
        missing = [i for i in batch if i not in got]
        if missing and runner.name == 'pytest' and DESELECTED.search(output):
            # Deselected by the project's configuration, not lost to an abort: skipped, and not split to find out.
            kept = runner.selected(python, tree, missing, env, max(deadline - time.monotonic(), 1))
            if kept is not None:
                found.update({ident: 'skipped' for ident in missing if ident not in kept})
                missing = [ident for ident in missing if ident in kept]
        if not missing:
            continue
        reason = None if got else abort_reason(output, tree)
        if not got:
            said, last = reason.split(' (at ')[0], (output.strip().splitlines() or [''])[-1]
            # A refusal that comes back for a batch without its group was not about the group.
            for key, before in runner.refused.copy().items():
                if key[0] == where and before == said and all(runner.group(i) != key[1] for i in batch):
                    runner.refused.pop(key, None)
            group = refusal(runner, f'{said}\n{last}', batch)
            if group is not None:
                # The runner refuses a whole label group before any test runs: its labels are unrunnable, here and in
                # later batches, and the rest runs without them. Splitting would find them one restart at a time.
                runner.refused[where, group] = said
                found.update({i: 'unrunnable' for i in usable if runner.group(i) == group and i not in found})
                batches = [[i for i in rest if runner.group(i) != group] for rest in [missing, *batches]]
                continue
        if not got and not splits and first_error is None:
            first_error = reason
        elif (not got and splits and len(batch) > 1 and not any(state != 'unrunnable' for state in found.values())
              and reason == first_error):
            # Half a batch failing exactly as the whole batch did: the runner aborts before any test, whatever
            # the labels. Splitting further only restarts it; every remaining candidate is unrunnable.
            for ident in [*missing, *(i for rest in batches for i in rest)]:
                found[ident] = 'unrunnable'
            batches = []
            continue
        if len(missing) == 1 or splits >= MAX_SPLITS:
            for ident in missing:
                found[ident] = 'unrunnable'
            continue
        splits += 1
        half = len(missing) // 2
        batches.extend([missing[:half], missing[half:]])
    if all(found.get(i) == 'unrunnable' for i in usable):
        said = first_error or next(filter(None, (runner.refused.get((where, runner.group(i))) for i in usable)), None)
        problem = 'no outcomes read: ' + (said or 'the runner produced no result for any candidate')
    return found, problem


